namespace HomeMaintenanceMAUI;
// The AppShell class defines the main structure and navigation of the application.
// It inherits from the Shell class, which provides a way to organize the app's pages and navigation and is automatically generated by the .NET MAUI framework.
public partial class AppShell : Shell
{   // The constructor initializes the AppShell and registers routes for navigation.
    public AppShell()
    {   // Initialize the components defined in the XAML file.
        InitializeComponent();
        // Register the route for the CreateAccountPage.
        Routing.RegisterRoute(
            nameof(CreateAccountPage),
            typeof(CreateAccountPage));
        // Register the route for the DashboardPage.
        Routing.RegisterRoute(
            nameof(DashboardPage),
            typeof(DashboardPage));
    Routing.RegisterRoute(
            nameof(DashboardPage),
            typeof(DashboardPage));
  }
}
